from playwright.sync_api import sync_playwright
URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
with sync_playwright() as p:
    b = p.chromium.launch()
    for w, h in [(1920,930),(1440,900),(768,1024),(390,844)]:
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(URL + "?preview=process-01")
        pg.wait_for_timeout(700)
        r = pg.evaluate("""() => {
          const sheet = document.querySelector('.process-sheet');
          const sr = sheet.getBoundingClientRect();
          const bandH = parseFloat(getComputedStyle(document.getElementById('process')).getPropertyValue('--band-h'));
          const stick = document.querySelector('.process-stick');
          const stR = stick.getBoundingClientRect();
          return {sheetW: sr.width, sheetH: sr.height, vwPct: sr.width/window.innerWidth*100,
                  bandH, stickRight: stR.right, clientWidth: document.documentElement.clientWidth};
        }""")
        print(w, r)
        pg.close()
    b.close()

