from playwright.sync_api import sync_playwright
URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
with sync_playwright() as p:
    b = p.chromium.launch()
    for w, h in [(1920,930),(1440,900)]:
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(URL + "?preview=process-01")
        pg.wait_for_timeout(700)
        r = pg.evaluate("""() => {
          const bands = Array.from(document.querySelectorAll('.step-band'));
          let tallest = null, tallestH = 0;
          for (const b of bands){ if (b.scrollHeight > tallestH){ tallestH = b.scrollHeight; tallest = b; } }
          const num = tallest.querySelector('.ledger-num');
          const title = tallest.querySelector('.process-step-title');
          const p = tallest.querySelector('.process-p');
          const numR = num.getBoundingClientRect(), titleR = title.getBoundingClientRect(), pR = p.getBoundingClientRect();
          const cs = getComputedStyle(tallest);
          return {
            step: tallest.closest('li').dataset.step,
            bandScrollH: tallestH,
            padTop: cs.paddingTop, padBottom: cs.paddingBottom, rowGap: cs.rowGap,
            numH: numR.height, titleH: titleR.height, pH: pR.height, pWidth: pR.width,
            pLineCount: Math.round(pR.height / parseFloat(getComputedStyle(p).lineHeight)),
            processStepsWidth: document.querySelector('.process-steps').getBoundingClientRect().width,
          };
        }""")
        print(w, r)
        pg.close()
    b.close()

