995	     Geists faktiska glyfbredd, samma metod: mät bredden, lös för 90%
996	     av spalten). Måste räknas om igen den dag de riktiga typsnitten
997	     laddas (Q2 godkänd). Taket höjt 9rem->12rem: Cardo-taket (144px)
998	     klippte Geist-kursiven till 75% av spalten vid 1920 i stället för
999	     90% - 12rem (192px) ger plats åt 33cqi:s 172px innan taket slår till. */
1000	  .case-name{display:block;line-height:.9;font-size:min(12rem,var(--name-fit));}
1001	  .case--calyx .case-name{font-family:var(--f-quote-calyx);font-style:italic;font-weight:400;
1002	    --name-fit:33cqi;letter-spacing:-.01em;}
1003	  .case--horai .case-name{font-family:var(--f-quote-horai);font-weight:600;
1004	    text-transform:uppercase;letter-spacing:.06em;--name-fit:26cqi;}
1005	  .case-line{display:block;margin-top:clamp(14px,2svh,22px);max-width:20ch;
1006	    font-family:var(--font);font-weight:300;font-size:clamp(1.75rem,2.3vw,2.75rem);
1007	    line-height:1.08;letter-spacing:-.015em;text-wrap:balance;}
1008	  .case-steps{list-style:none;margin:clamp(28px,5svh,48px) 0 0;padding:0;display:grid;}
1009	  .cs{grid-area:1/1;min-width:0;}
1010	  .cs h3{font-family:var(--f-display);font-weight:700;font-size:clamp(1.5rem,2.2vw,2rem);
1011	    line-height:1.05;letter-spacing:-.01em;text-transform:uppercase;}
1012	  .cs p{font-size:clamp(1.0625rem,1.4vw,1.25rem);line-height:1.55;max-width:36ch;margin-top:.7rem;
1013	    color:color-mix(in srgb,var(--ink) 80%,var(--bg));}
1014	  /* Samma springa som tesens .ts (--in/--out/clip-path/transform/letter-
1015	     spacing), N ur sektionens egen --n (Calyx 5, Hōrai 6). Astra r7
1016	     material_fixes #3: samma symmetriska ±f/2-bugg som tesen (fix 1) -
1017	     asymmetriska fönster, se kommentaren vid .js .ts. */
1018	  .case--calyx{--n:5;} .case--horai{--n:6;}
1019	  /* PLAN 060 4.3: --q är aktens progress skalad till stegfönstret 0..--t
1020	     (Calyx .86, Hōrai 1 - oförändrad per konstruktion). Stegformlerna läser
1021	     --q i stället för rå --sc-ps, så alla fem/sex Calyx-steg ryms inom de
1022	     första 86% av aktens liv, exakt i takt med latchTick/caseY (JS). */
1023	  .js .cs{--q:min(1, var(--sc-ps,0) / var(--t,1));
1024	    --a:calc(var(--i) / var(--n));--b:calc((var(--i) + 1) / var(--n));--f:.04;
1025	    --in:clamp(0,calc((var(--q) - var(--a)) / var(--f)),1);
1026	    --out:clamp(0,calc((var(--q) - (var(--b) - var(--f))) / var(--f)),1);
1027	    clip-path:inset(calc(var(--out) * 100%) 0 calc((1 - var(--in)) * 100%) 0);
1028	    transform:translateY(calc((1 - var(--in)) * .55em - var(--out) * .55em));
1029	    letter-spacing:calc(-.01em + (1 - var(--in)) * .06em);}
1030	  .js .cs:first-child{--in:1;} .js .cs:last-child{--out:0;}
1031	  /* PLAN 060 7.2 (F-016): .case-rail (sidomenyn, en andra kopia av
1032	     stegrubrikerna) är borta - stegens egna h3 bär informationen. */
1033	  /* PLAN 060 4.2. Calyx -> Hōrai utan brygga (B3): stegen ryms i 0..--t,
1034	     sedan lämnar textspalten (lager 1) och grunden blir svart (lager 2)
1035	     medan ramen står still. INTE en tredje sektion, INTE en hård kant
1036	     papper/svart, ramen transformeras/tonas/klipps aldrig. */
1037	  .case--calyx{--t:.86;} .case--horai{--t:1;}
1038	  .case-gap{height:clamp(96px,18svh,200px);background:var(--c-black);}
1039	  .js .case--calyx{
1040	    --x1:clamp(0,calc((var(--sc-ps,0) - .87) / .04),1);
1041	    --x2:clamp(0,calc((var(--sc-ps,0) - .91) / .08),1);}
1042	  .js .case--calyx .case-text{
1043	    clip-path:inset(calc(var(--x1) * 100%) 0 0 0);
1044	    transform:translateY(calc(var(--x1) * -32px));}
1045	  .js .case--calyx .case-stage{
1046	    background:color-mix(in oklab,var(--bg),var(--c-black) calc(var(--x2) * 100%));}
1047	  @media (max-width:767px){
1048	    /* Astra r7 material_fixes #5: 52svh gav case-fig 438,9px vid 844,
1049	       minus bildtextens ~39px = 400px = 47,4%vh (mål >=50%/422px).
1050	       58svh: 489,5-39=450,5px=53,4%vh. Astra r8 material_fixes #3: 450px
1051	       räcker inte för Calyx steg 3 (figur+bildtext 484px, uppmätt direkt
1052	       i sites/calyx.html). 66svh: 557-39=517,5px - rymmer 484px med
1053	       marginal. */
1054	    .case-stage,.case--horai .case-stage{grid-template-columns:minmax(0,1fr);
1055	      grid-template-rows:66svh minmax(0,1fr);padding:0 0 clamp(16px,3svh,24px);}
1056	    /* Astra r8 material_fixes #1: Hōrais citat (case-horai-03) centreras
1057	       sant i ramen, men vid en 450px ram hamnar det delvis bakom sajtens
1058	       egen nav (sites/horai.html, orörd). Astras måltal: ih>=625px
1059	       centrerat, eller ih>=525px med ankaret 100px ovanför centrum. En
1060	       Hōrai-specifik rad (samma specificitet som den delade regeln
1061	       ovan, senare i källordningen vinner den) höjer ih till ~568px;
1062	       measureCase() nedan lägger sedan ett -100px-offset på just
1063	       Hōrais citat-ankare när ramen är kort. */
1064	    .case--horai .case-stage{grid-template-rows:72svh minmax(0,1fr);}
1065	    .case .case-fig{grid-column:1;grid-row:1;}
1066	    .case .case-text{grid-column:1;grid-row:2;justify-content:flex-start;
1067	      padding:clamp(16px,3svh,24px) var(--rail-x) 0;}
1068	    .case-title{margin-top:0;}
1069	    .case-name{font-size:2.25rem;}
