  /* PLAN 067 6.4 (B13). mailto:-submit: ingen backend (PRODUCT.md § Operating
     Context), webbläsarens egen validering (reportValidity), fälten töms
     aldrig, ingen "Tack"-vy. SUBJECT/STATUS finns inte som egna rader i
     COPY-V3d-r23.md (bara K-H1/K-SUB/K-F1-3/K-BTN/K-ALT är låsta där) -
     texten här uppfyller planens egna Copy-krav ordagrant (6.4: nämner
     kontakt@alunix.se, säger att mejlet är förberett) och är flaggad i
     NOTES för Anton, inte tyst påhittad marknadsföring. */
  var kf = document.querySelector('.contact-form');
  if (kf) kf.addEventListener('submit', function(e){
    e.preventDefault();
    if (!kf.reportValidity()) return;
    var v = function(n){ return (kf.elements[n].value || '').trim(); };
    var SUBJECT = 'Kontakt från alunix.se';
    var STATUS = 'Mejlet är förberett och skickas när ni bekräftar det i er e-postklient. Öppnades ingen klient, mejla direkt till kontakt@alunix.se.';
    var body = [v('namn'), v('verksamhet'), '', v('text')].join('\n');
    location.href = 'mailto:kontakt@alunix.se'
      + '?subject=' + encodeURIComponent(SUBJECT)
      + '&body=' + encodeURIComponent(body);
    kf.querySelector('.contact-status').textContent = STATUS;
  });
})();

