2626	  function measureAct(){
2627	    if (thesisEl){ var tr = thesisEl.getBoundingClientRect(); thesisTop = tr.top + window.scrollY; thesisH = tr.height; }
2628	    if (process){
2629	      var pr = process.getBoundingClientRect();
2630	      processTop = pr.top + window.scrollY;
2631	      processH = pr.height;
2632	
2633	      var lis = process.querySelectorAll('.process-steps li');
2634	      var vh = window.innerHeight;
2635	      var top = processTop, stick = process.querySelector('.process-stick');
2636	      var mobile = window.matchMedia('(max-width:767px)').matches;
2637	      var sheetH = 0;
2638	      /* PLAN 048 F step 16, tal rättade PLAN 067 2.4. --band-h (och på
2639	         mobil även --sheet-h) skrivs FÖRE li-rektanglarna läses: stegens
2640	         min-height beror på talet (>=1024: band-h + 72svh; mobil: band-h
2641	         + 48svh, sedan 067), så en läsning innan skrivningen vore
2642	         inaktuell. */
2643	      /* PLAN 067 2.2. Mobilens .step-band är nu sticky under arket (B7),
2644	         med samma --band-h-beroende höjd desktop redan har - mätningen
2645	         skrivs därför BÅDA --sheet-h och --band-h på mobil också, i den
2646	         ordningen (sheet-h styr slottens top-tröskel, band-h dess egen
2647	         höjd), inte bara --sheet-h som tidigare (det fanns ingen sticky
2648	         mobilband att mäta höjd på förut). */
2649	      if (mobile && stick){
2650	        sheetH = stick.getBoundingClientRect().height;
2651	        process.style.setProperty('--sheet-h', sheetH.toFixed(1) + 'px');
2652	      }
2653	      var bands = process.querySelectorAll('.step-band');
2654	      var bandH = 0;
2655	      for (var b = 0; b < bands.length; b++){ bandH = Math.max(bandH, bands[b].scrollHeight); }
2656	      bandH = Math.ceil(bandH);
2657	      if (bandH && bandH !== lastBandH){
2658	        lastBandH = bandH;
2659	        process.style.setProperty('--band-h', bandH + 'px');
2660	      }
2661	      /* PLAN 061 1.3 (Blåkopian). Läses HÄR, efter att --band-h/--sheet-h
2662	         satt arkets slutliga mått: linjernas x = arkets egna stationer
2663	         (samma tal som #p-open/måttkedjan, 195,6/469,3 av 880), en gång
2664	         per mätning som --band-h/--life, aldrig per bildruta. */
2665	      var chapterEl = process.querySelector('.process-chapter');
2666	      var sheetEl = process.querySelector('.process-sheet');
2667	      var titleEl = document.getElementById('process-title');
2668	      if (chapterEl && sheetEl && titleEl){
2669	        var C = chapterEl.getBoundingClientRect();
2670	        var L = sheetEl.getBoundingClientRect();
2671	        var T = titleEl.getBoundingClientRect();
2672	        var x1 = L.left, x2 = L.left + L.width * 195.6 / 880,
2673	            x3 = L.left + L.width * 469.3 / 880, x4 = L.left + L.width - 1;
2674	        chapterEl.style.setProperty('--x1', (x1 - C.left).toFixed(1) + 'px');
2675	        chapterEl.style.setProperty('--x2', (x2 - C.left).toFixed(1) + 'px');
2676	        chapterEl.style.setProperty('--x3', (x3 - C.left).toFixed(1) + 'px');
2677	        chapterEl.style.setProperty('--x4', (x4 - C.left).toFixed(1) + 'px');
2678	        chapterEl.style.setProperty('--dn', Math.max(0, T.top - C.top - 40).toFixed(1) + 'px');
2679	        /* PLAN 062 B1, rättad live denna runda (geometrisk kontroll fann
2680	           .tes-plane över P.ts vid tidiga scrollägen). Ett FAST
2681	           100vh-plan reste sig högre än den fria blå ytan B3 (2061)
2682	           redan mätte upp - #tes:s EGEN sticky-scen står kvar (still
2683	           pinnad) längre än 100vh ovanför kanten på vissa bredder, så
2684	           planet (opakt, samma z-index-lager som redan vinner över #tes)
2685	           målade rakt över levande stegtext INNAN dess pin ens släppt.
2686	           Planets EGEN höjd ovanför kanten begränsas nu av EXAKT samma
2687	           "fri" som --upN redan använder (stage.bottom - lägsta av
2688	           foto/.ts-underkanter): en yta som per konstruktion ALDRIG har
2689	           levande tesinnehåll, oavsett bredd. "En hel skärm" blir alltså
2690	           "så mycket blått som säkert kan visas", inte ett hårdkodat
2691	           100vh - samma säkerhetsmarginal som linjerna (B3) redan är
2692	           byggda och verifierade mot. */
2693	        var stageEl = document.querySelector('.thesis-stage');
2694	        var photoEl = document.querySelector('.thesis-photo-box');
2695	        var tsEls = document.querySelectorAll('.ts');
2696	        var tickEls = document.querySelectorAll('.thesis-ticks i');
2697	        var fri = 0;
2698	        if (stageEl){
2699	          var stageR = stageEl.getBoundingClientRect();
2700	          var lowest = photoEl ? photoEl.getBoundingClientRect().bottom : 0;
2701	          for (var ti = 0; ti < tsEls.length; ti++){
2702	            lowest = Math.max(lowest, tsEls[ti].getBoundingClientRect().bottom);
2703	          }
2704	          fri = Math.max(0, stageR.bottom - lowest);
2705	        }
2706	        var planeH = Math.min(fri, vh);
