function measureAct(){
  if (thesisEl){ var tr = thesisEl.getBoundingClientRect(); thesisTop = tr.top + window.scrollY; thesisH = tr.height; }
  if (process){
    var pr = process.getBoundingClientRect();
    processTop = pr.top + window.scrollY;
    processH = pr.height;

    var lis = process.querySelectorAll('.process-steps li');
    var vh = window.innerHeight;
    var top = processTop, stick = process.querySelector('.process-stick');
    var mobile = window.matchMedia('(max-width:767px)').matches;
    var sheetH = 0;
    /* PLAN 048 F step 16, tal rättade PLAN 067 2.4. --band-h (och på
       mobil även --sheet-h) skrivs FÖRE li-rektanglarna läses: stegens
       min-height beror på talet (>=1024: band-h + 72svh; mobil: band-h
       + 48svh, sedan 067), så en läsning innan skrivningen vore
       inaktuell. */
    /* PLAN 067 2.2. Mobilens .step-band är nu sticky under arket (B7),
       med samma --band-h-beroende höjd desktop redan har - mätningen
       skrivs därför BÅDA --sheet-h och --band-h på mobil också, i den
       ordningen (sheet-h styr slottens top-tröskel, band-h dess egen
       höjd), inte bara --sheet-h som tidigare (det fanns ingen sticky
       mobilband att mäta höjd på förut). */
    if (mobile && stick){
      sheetH = stick.getBoundingClientRect().height;
      process.style.setProperty('--sheet-h', sheetH.toFixed(1) + 'px');
    }
    var bands = process.querySelectorAll('.step-band');
    var bandH = 0;
    for (var b = 0; b < bands.length; b++){ bandH = Math.max(bandH, bands[b].scrollHeight); }
    bandH = Math.ceil(bandH);
    if (bandH && bandH !== lastBandH){
      lastBandH = bandH;
      process.style.setProperty('--band-h', bandH + 'px');
    }
    /* PLAN 061 1.3 (Blåkopian). Läses HÄR, efter att --band-h/--sheet-h
       satt arkets slutliga mått: linjernas x = arkets egna stationer
       (samma tal som #p-open/måttkedjan, 195,6/469,3 av 880), en gång
       per mätning som --band-h/--life, aldrig per bildruta. */
    var chapterEl = process.querySelector('.process-chapter');
    var sheetEl = process.querySelector('.process-sheet');
    var titleEl = document.getElementById('process-title');
    if (chapterEl && sheetEl && titleEl){
      var C = chapterEl.getBoundingClientRect();
      var L = sheetEl.getBoundingClientRect();
      var T = titleEl.getBoundingClientRect();
      var x1 = L.left, x2 = L.left + L.width * 195.6 / 880,
          x3 = L.left + L.width * 469.3 / 880, x4 = L.left + L.width - 1;
      chapterEl.style.setProperty('--x1', (x1 - C.left).toFixed(1) + 'px');
      chapterEl.style.setProperty('--x2', (x2 - C.left).toFixed(1) + 'px');
      chapterEl.style.setProperty('--x3', (x3 - C.left).toFixed(1) + 'px');
      chapterEl.style.setProperty('--x4', (x4 - C.left).toFixed(1) + 'px');
      chapterEl.style.setProperty('--dn', Math.max(0, T.top - C.top - 40).toFixed(1) + 'px');
      /* PLAN 062 B1, rättad live denna runda (geometrisk kontroll fann
         .tes-plane över P.ts vid tidiga scrollägen). Ett FAST
         100vh-plan reste sig högre än den fria blå ytan B3 (2061)
         redan mätte upp - #tes:s EGEN sticky-scen står kvar (still
         pinnad) längre än 100vh ovanför kanten på vissa bredder, så
         planet (opakt, samma z-index-lager som redan vinner över #tes)
         målade rakt över levande stegtext INNAN dess pin ens släppt.
         Planets EGEN höjd ovanför kanten begränsas nu av EXAKT samma
         "fri" som --upN redan använder (stage.bottom - lägsta av
         foto/.ts-underkanter): en yta som per konstruktion ALDRIG har
         levande tesinnehåll, oavsett bredd. "En hel skärm" blir alltså
         "så mycket blått som säkert kan visas", inte ett hårdkodat
         100vh - samma säkerhetsmarginal som linjerna (B3) redan är
         byggda och verifierade mot. */
      var stageEl = document.querySelector('.thesis-stage');
      var photoEl = document.querySelector('.thesis-photo-box');
      var tsEls = document.querySelectorAll('.ts');
      var tickEls = document.querySelectorAll('.thesis-ticks i');
      var fri = 0;
      if (stageEl){
        var stageR = stageEl.getBoundingClientRect();
        var lowest = photoEl ? photoEl.getBoundingClientRect().bottom : 0;
        for (var ti = 0; ti < tsEls.length; ti++){
          lowest = Math.max(lowest, tsEls[ti].getBoundingClientRect().bottom);
        }
        fri = Math.max(0, stageR.bottom - lowest);
      }
      var planeH = Math.min(fri, vh);
      chapterEl.style.setProperty('--pl-h', planeH.toFixed(1) + 'px');
      /* PLAN 063, fynd denna runda: .process-sheet byter till 320/200
         under 768 (rad ~1640, K3-registret) - 495/880 var hårdkodat
         obetingat sedan plan 062, aldrig fel synligt förrän frysmålet
         jämfördes pixel mot pixel med det riktiga arket (±11px fel vid
         390, verify_continuity.py). Samma brytpunkt som CSS:n. */
      var sheetAspect = window.innerWidth < 768 ? 200 / 320 : 495 / 880;
      var pW = x4 - x1;
      var pH = pW * sheetAspect;
      var planeTop = C.top - planeH;
      var landingY = T.top - 40;
      var pTop = landingY - pH;
      chapterEl.style.setProperty('--pl-t', Math.max(0, pTop - planeTop).toFixed(1) + 'px');
      /* PLAN 066 fynd 2 (Astra r21). .tes-plane är CSS 100vw - bredare än
         window.innerWidth (clientWidth) med rullningslistens bredd - och
         translateX(-50%)-centrerad, så dess EGEN vänsterkant sitter vid
         -scrollbarWidth/2, inte 0. --pl-r/--pl-l räknade tidigare mot
         innerWidth/0, gav +5/-6px fel mot --x1/--x4 (uppmätt, contour2.json).
         Läser planets EGEN getBoundingClientRect() i stället. */
      var planeElNow = process.querySelector('.tes-plane');
      var planeBox = planeElNow ? planeElNow.getBoundingClientRect() : { left: 0, right: window.innerWidth };
      chapterEl.style.setProperty('--pl-r', Math.max(0, planeBox.right - x4).toFixed(1) + 'px');
      chapterEl.style.setProperty('--pl-l', Math.max(0, x1 - planeBox.left).toFixed(1) + 'px');
      /* B3: den blå delen finns bara där det blå är tomt. 0 om < 64px
         eller om linjen x krockar tickstrecken ±16px, annars
         min(fri - 32, 22svh). */
      if (stageEl){
        var tickRects = [];
        for (var ki = 0; ki < tickEls.length; ki++) tickRects.push(tickEls[ki].getBoundingClientRect());
        var xs = [x1, x2, x3, x4];
        for (var xi = 0; xi < 4; xi++){
          var hitsTick = tickRects.some(function(r){ return xs[xi] >= r.left - 16 && xs[xi] <= r.right + 16; });
          var up = (fri < 64 || hitsTick) ? 0 : Math.min(fri - 32, 0.22 * vh);
          chapterEl.style.setProperty('--up' + (xi + 1), Math.max(0, up).toFixed(1) + 'px');
        }
      }
    }
    var processRect2 = process.getBoundingClientRect();
    processTop = processRect2.top + window.scrollY;

