/* PLAN 067 4.1: min-height:100svh bort - Exempelcase var sidans STÖRSTA
   ord (136px, större än processrubrikens 120 och tesens 96) och sög luft
   ur ett helt skärmfönster för att göra det. Padding bär nu blockets
   höjd, inte en tvingad skärmhöjd. */
.cases-chapter{background:var(--bg);color:var(--ink);display:flex;
  flex-direction:column;justify-content:center;
  padding:clamp(56px,14svh,140px) var(--rail-x) clamp(32px,7svh,72px);}

input.new_string:
/* PLAN 067 4.1: min-height:100svh bort - Exempelcase var sidans STÖRSTA
   ord (136px, större än processrubrikens 120 och tesens 96) och sög luft
   ur ett helt skärmfönster för att göra det. Padding bär nu blockets
   höjd, inte en tvingad skärmhöjd. */
.cases-chapter{background:var(--bg);color:var(--ink);display:flex;
  flex-direction:column;justify-content:center;position:relative;
  padding:clamp(56px,14svh,140px) var(--rail-x) clamp(32px,7svh,72px);}
/* PLAN 067 5.2. Ritningsarket öppnar sig till kapitlets papper. Samma
   inset()-grammatik och samma --pl-*-mönster som .tes-plane, spegelvänd.
   INTE en hård kant, INTE en gradient, INTE en fjärde mekanik. */
.cases-chapter{--cx:clamp(0,calc(var(--sc-ps,0) / .34),1);}
.chapter-plate{position:absolute;left:50%;width:100vw;transform:translateX(-50%);
  top:calc(-1 * var(--cp-up,0px));height:calc(var(--cp-up,0px) + 100%);
  pointer-events:none;z-index:0;
  background:color-mix(in oklab,var(--c-drafting),var(--bg) calc(var(--cx) * 100%));
  clip-path:inset(calc((1 - var(--cx)) * var(--cp-t,0px))
                  calc((1 - var(--cx)) * var(--cp-r,0px))
                  calc((1 - var(--cx)) * var(--cp-b,0px))
                  calc((1 - var(--cx)) * var(--cp-l,0px)));}
.cases-chapter > :not(.chapter-plate){position:relative;z-index:1;}
html:not(.js) .chapter-plate{display:none;}
/* PLAN 067 5.4: landningshårlinjen, samma roll som .tes-plane-övergångens
   egen (§ keep) - ingen etikett, ingen siffra (F-016). */
.cases-chapter::after{content:"";position:absolute;z-index:2;pointer-events:none;
  left:0;width:calc(100% - var(--cp-l,0px) - var(--cp-r,0px));
  top:calc(var(--dn2,0px) - 40px);height:1px;background:var(--c-line-on-paper);
  clip-path:inset(0 calc((1 - clamp(0,calc((var(--cx) - .62) / .2),1)) * 100%) 0 0);}

