from playwright.sync_api import sync_playwright
URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
with sync_playwright() as p:
    b = p.chromium.launch()
    for w, h in [(1920,930),(1440,900),(390,844)]:
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(URL)
        pg.wait_for_timeout(500)
        r = pg.evaluate("""() => {
          const caseEl = document.getElementById('case');
          const cs = getComputedStyle(caseEl);
          const plate = caseEl.querySelector('.chapter-plate');
          const cx0 = plate.getBoundingClientRect();
          const cpUp = cs.getPropertyValue('--cp-up');
          const cpT = cs.getPropertyValue('--cp-t');
          const cpB = cs.getPropertyValue('--cp-b');
          const cpR = cs.getPropertyValue('--cp-r');
          const cpL = cs.getPropertyValue('--cp-l');
          const cpDn = cs.getPropertyValue('--cp-dn');
          const process = document.getElementById('process');
          const stick = process.querySelector('.process-stick');
          const sheet = process.querySelector('.process-sheet');
          const pr = process.getBoundingClientRect();
          const stickPB = parseFloat(getComputedStyle(stick).paddingBottom)||0;
          // analytic resting ark rect in doc coords
          const processTop = pr.top + window.scrollY;
          const arkBottomDoc = processTop + pr.height - stickPB;
          return {w: window.innerWidth, cpUp, cpT, cpB, cpR, cpL, cpDn,
                  plateAtLoad: {top: cx0.top, left: cx0.left, width: cx0.width, height: cx0.height},
                  processH: pr.height, arkBottomDoc, sheetAspectW: sheet.getBoundingClientRect().width};
        }""")
        print(w, r)
        pg.close()
    b.close()

