from playwright.sync_api import sync_playwright
import sys, os
URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
OUT = "C:/Users/Anton L/anti-slop-design/tests/alunix-r8/runs/V3d/shots/r23"
os.makedirs(OUT, exist_ok=True)
ps = float(sys.argv[1])
w, h = (int(sys.argv[2]), int(sys.argv[3])) if len(sys.argv) > 3 else (1920, 930)
with sync_playwright() as p:
    b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
    pg = b.new_page(viewport={"width": w, "height": h})
    pg.goto(URL)
    pg.wait_for_timeout(400)
    pg.evaluate("""(ps) => {
      window.__scFreezeMotion = true;
      const el = document.getElementById('case');
      const travel = Math.max(0, el.offsetHeight - window.innerHeight);
      const top = el.getBoundingClientRect().top + window.scrollY;
      window.scrollTo(0, Math.round(top + ps * travel));
      dispatchEvent(new Event('resize'));
    }""", ps)
    pg.wait_for_timeout(500)
    got = pg.evaluate("() => getComputedStyle(document.getElementById('case')).getPropertyValue('--sc-ps')")
    print("actual --sc-ps:", got)
    pg.screenshot(path="%s/case-ps%s-%d.png" % (OUT, str(ps).replace('.','_'), w))
    pg.close()
    b.close()

