/* Impeccable harden, Disabled/Loading-raderna: knappen stängs av under den
   korta mailto-handoffen (skyddar mot ett dubbelklick som öppnar två
   e-postfönster - Target 6 kräver 0 nätverksanrop, men två mailto-öppningar
   är sin egen defekt) och etiketten byter till en verbform, ingen
   sidreferens (F-018). aria-disabled räcker inte ensamt för knappar -
   disabled tar bort den ur tabbordningen medan handoffen pågår, sedan
   återställs båda av samma submit-hanterare. */
.contact-send:disabled{opacity:.5;cursor:not-allowed;}
.contact-status:empty{display:none;}
.contact-status{font-family:var(--font);font-weight:300;
  font-size:clamp(1.0625rem,.85rem + .28vw,1.1875rem);line-height:1.45;
  color:var(--ink);max-width:48ch;}
html:not(.js) .contact-send{display:none;}

