input.new_string:
if (kf){
  /* Impeccable harden, Error-kanalen: aria-invalid satt/rensat per fält,
     oberoende av :user-invalid:s webbläsarstöd - skärmläsaren ska alltid
     få kanalen, inte bara den visuella. */
  Array.prototype.forEach.call(kf.querySelectorAll('input,textarea'), function(el){
    el.addEventListener('input', function(){
      if (el.validity.valid) el.removeAttribute('aria-invalid');
    });
  });
  kf.addEventListener('submit', function(e){
    e.preventDefault();
    if (!kf.reportValidity()){
      Array.prototype.forEach.call(kf.querySelectorAll('input,textarea'), function(el){
        if (!el.validity.valid) el.setAttribute('aria-invalid', 'true');
      });
      return;
    }
    var v = function(n){ return (kf.elements[n].value || '').trim(); };
    var SUBJECT = 'Kontakt från alunix.se';
    var STATUS = 'Mejlet är förberett och skickas när ni bekräftar det i er e-postklient. Öppnades ingen klient, mejla direkt till kontakt@alunix.se.';
    var body = [v('namn'), v('verksamhet'), '', v('text')].join('\n');
    /* Impeccable harden, Disabled/Loading-kanalen: knappen av under den
       korta mailto-handoffen (skyddar mot dubbelklick = två e-postfönster,
       Target 6:s "0 nätverksanrop" gäller ändå - detta är ingen begäran),
       etiketten byter till en verbform. Ingen sidreferens (F-018). */
    var btn = kf.querySelector('.contact-send');
    var label = btn.textContent;
    btn.disabled = true;
    btn.textContent = 'Öppnar…';
    location.href = 'mailto:kontakt@alunix.se'
      + '?subject=' + encodeURIComponent(SUBJECT)
      + '&body=' + encodeURIComponent(body);
    kf.querySelector('.contact-status').textContent = STATUS;
    setTimeout(function(){ btn.disabled = false; btn.textContent = label; }, 900);
  });
}

