/* PLAN 067 7.2/Target 7:4 (river fönstret .78->.22): rubriken ska vara
   läsbar vid tx ≈ 0,45, medan arket fortfarande konvergerar - inte vänta
   tills draget nästan är över. --p-edge (0,6->0,9, § keep) rörs inte. */
.js .process-title{--edge:calc(clamp(0,calc((var(--tx) - .38) / .32),1) * 130%);
  background-image:linear-gradient(100deg,var(--ink) 0 calc(var(--edge) - 12%),
    color-mix(in srgb,var(--ink) 62%,var(--bg)) calc(var(--edge) + 12%) 100%);
  -webkit-background-clip:text;background-clip:text;color:transparent;}
/* PLAN 067 C9/7.2 (Astra r23 material_fix 4). Prickarna var det enda
   märket i ett tomt blått fält genom hela övergången - släcks nu när
   tesens sista mening lämnar bildrutan (tesens EGEN --sc-ps, F-014,
   reversibel båda hållen). */
.js .thesis-ticks{opacity:clamp(0,calc((.96 - var(--sc-ps,0)) / .04),1);}
html:not(.js) .seam,html:not(.js) .tes-plane{display:none;}

