from playwright.sync_api import sync_playwright
URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
with sync_playwright() as p:
    b = p.chromium.launch()
    for w, h in [(1920,930),(1440,900),(390,844)]:
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(URL)
        pg.wait_for_timeout(400)
        info = pg.evaluate("""() => {
          const chapterEl = document.querySelector('.process-chapter');
          const cs = getComputedStyle(chapterEl);
          const txA = parseFloat(cs.getPropertyValue('--tx-a'));
          const txB = parseFloat(cs.getPropertyValue('--tx-b'));
          const dn = parseFloat(cs.getPropertyValue('--dn'));
          const stampH = parseFloat(cs.getPropertyValue('--stamp-h'));
          const life = chapterEl.offsetHeight + window.innerHeight;
          const drawPx = txB * life;
          const chapterHeight = chapterEl.getBoundingClientRect().height;
          const stamp = chapterEl.querySelector('.chapter-stamp');
          const stampBox = stamp.getBoundingClientRect();
          const title = document.getElementById('process-title');
          const titleBox = title.getBoundingClientRect();
          return {drawPx, chapterHeight, dn, stampH, stampTop: stampBox.top - chapterEl.getBoundingClientRect().top,
                  titleFontSize: getComputedStyle(title).fontSize, txA, txB};
        }""")
        print(w, info)
        pg.close()
    b.close()

